mapper.select:
SELECT
  
FROM product p

WHERE p.prod_no = #{value}

  SELECT * FROM (
    SELECT inner_t.*, ROWNUM AS rnum
    FROM (
      SELECT
        
        
        
      FROM product p
      
      
      
        

  AND p.status = 'Y'

      
      
        
        
          AND TO_CHAR(p.prod_no) LIKE '%' || #{searchKeyword} || '%'
        
        
        
          AND LOWER(p.prod_name) LIKE LOWER('%' || #{searchKeyword} || '%')
        
        
        
          AND p.price = #{searchKeyword, jdbcType=INTEGER}
        
      
      ORDER BY p.prod_no DESC
    ) inner_t
    WHERE ROWNUM <= #{endRowNum}
  )
  WHERE rnum >= #{startRowNum}

SELECT status
  FROM product
 WHERE prod_no = #{value}
